const btn = document.getElementById("btn-single");

btn.addEventListener("click", function (e) {
  console.log("Klikniete!", e.type, e.target);
});
// "Klikniete! click <button id='btn-single'>..."

function onBtnClick(e) {
  console.log("Obsluga klikniecia");
}

btn.addEventListener("click", onBtnClick);
btn.removeEventListener("click", onBtnClick); // usuwa TEN KONKRETNY handler

btn.addEventListener("click", () => console.log("Tylko raz!"), { once: true });
// pierwsze klikniecie: "Tylko raz!"
// drugie klikniecie: NIC sie nie dzieje - handler juz 'zuzyty'

function pokazKlik() { console.log("klik"); }

btn.addEventListener("click", pokazKlik);
btn.removeEventListener("click", pokazKlik); // POPRAWNIE - ta sama referencja

exercises.solution:
function logClick(e) {
  console.log("log");
}

const btn = document.getElementById("btn-double");
btn.addEventListener("click", logClick);
btn.removeEventListener("click", logClick); // usuwa handler - klikniecie juz nic nie robi

const btn = document.getElementById("btn-single");

function handlerA() { console.log("A"); }
function handlerB() { console.log("B"); }

btn.addEventListener("click", handlerA);
btn.addEventListener("click", handlerB);
// jedno klikniecie wypisze OBA: "A" i "B"

// removeEventListener wymaga DOKLADNIE tej samej referencji funkcji,
// jaka zostala przekazana do addEventListener. Kazda arrow function
// zdefiniowana 'w miejscu' (np. () => console.log('klik')) tworzy NOWY,
// UNIKALNY obiekt funkcji w pamieci - nawet jesli DWIE takie funkcje maja
// identyczna tresc, sa to DWIE ROZNE referencje. Dlatego, aby moc pozniej
// usunac handler, MUSI on byc zapisany jako NAZWANA funkcja przypisana
// do zmiennej, uzywana identycznie w obu wywolaniach
// (addEventListener i removeEventListener).
